<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Apple's life cycle assessment methodology</title>
<style>
  :root {
    --text-main: #1d1d1f;
    --text-muted: #86868b;
    --apple-green: #00A82D;
    --bg-color: #ffffff;
    --font-stack: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  }

  body {
    margin: 0;
    padding: 40px 60px;
    font-family: var(--font-stack);
    background-color: var(--bg-color);
    color: var(--text-main);
    box-sizing: border-box;
    -webkit-font-smoothing: antialiased;
  }

  header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 90px;
  }

  .nav-links {
    display: flex;
    gap: 18px;
  }

  .nav-links span {
    cursor: default;
  }

  .nav-links .active {
    color: var(--text-main);
    font-weight: 500;
